
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_mbr_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_mbr", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.204562777425141e+00, -4.127861385155822e+00, -4.020578410528265e+00, -3.872372415984443e+00, -3.671274366824565e+00, -3.405365217136065e+00, -3.066365949623132e+00, -2.654596926563935e+00, -2.180789630203923e+00, -1.665464386468991e+00, -1.146965762810815e+00, -7.346630164986785e-01, -5.929384625872689e-01, -5.018559761233710e-01, -3.806714208587821e-01, -2.541134497633452e-01, -1.526500243845982e-01, -8.790390929464673e-02, -5.231833765714241e-02, -3.284062499429978e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


